{
  "schemaVersion": "scene-document/v2",
  "visualDecision": {
    "mode": "scene",
    "reason": "The stated inequalities define an exact graphable feasible region."
  },
  "source": {
    "question": "Use a graph to maximize Z = -x - y subject to x >= 0, y >= 0 and 2 <= x + y <= 6. Label the exact corners and the full set of optimal points.",
    "representationTier": "exact"
  },
  "quantities": [
    {"id": "xMin", "symbol": "x_min", "value": 0, "provenance": "given"},
    {"id": "yMin", "symbol": "y_min", "value": 0, "provenance": "given"},
    {"id": "sMin", "symbol": "(x+y)_min", "value": 2, "provenance": "given"},
    {"id": "sMax", "symbol": "(x+y)_max", "value": 6, "provenance": "given"},
    {"id": "coef", "symbol": "coefficient of x and y in Z", "value": -1, "provenance": "given"},
    {"id": "zMax", "symbol": "Z_max", "value": -2, "provenance": "derived", "dependsOn": ["sMin", "coef"]}
  ],
  "entities": [
    {"id": "ax", "kind": "axes", "role": "coordinate axes"},
    {"id": "region", "kind": "polygon", "role": "feasible region"},
    {"id": "c02", "kind": "point", "role": "corner", "label": "(0,2)"},
    {"id": "c20", "kind": "point", "role": "corner", "label": "(2,0)"},
    {"id": "c60", "kind": "point", "role": "corner", "label": "(6,0)"},
    {"id": "c06", "kind": "point", "role": "corner", "label": "(0,6)"},
    {"id": "optimal", "kind": "segment", "role": "full set of optimal points"}
  ],
  "constructions": [
    {"id": "kax", "operator": "axes", "inputs": {"xMin": -0.5, "xMax": 7, "yMin": -0.5, "yMax": 7}, "outputs": ["ax"]},
    {"id": "kregion", "operator": "linear_feasible_region", "inputs": {"variables": ["x", "y"], "constraints": ["x>=0", "y>=0", "x+y>=2", "x+y<=6"], "objective": {"expression": "-x-y", "sense": "max"}}, "outputs": ["region"]},
    {"id": "kc02", "operator": "point", "inputs": {"x": 0, "y": 2, "coordinateSpace": "world"}, "outputs": ["c02"]},
    {"id": "kc20", "operator": "point", "inputs": {"x": 2, "y": 0, "coordinateSpace": "world"}, "outputs": ["c20"]},
    {"id": "kc60", "operator": "point", "inputs": {"x": 6, "y": 0, "coordinateSpace": "world"}, "outputs": ["c60"]},
    {"id": "kc06", "operator": "point", "inputs": {"x": 0, "y": 6, "coordinateSpace": "world"}, "outputs": ["c06"]},
    {"id": "koptimal", "operator": "segment", "inputs": {"start": "c02", "end": "c20"}, "outputs": ["optimal"]}
  ],
  "relations": [],
  "assertions": [
    {"id": "end02", "predicate": "on", "entities": ["c02", "optimal"], "expected": true, "severity": "fatal"},
    {"id": "end20", "predicate": "on", "entities": ["c20", "optimal"], "expected": true, "severity": "fatal"}
  ],
  "annotations": [
    {"id": "objective", "kind": "label", "targetIds": ["region"], "text": "Z = -x - y"},
    {"id": "optimalSet", "kind": "highlight", "targetIds": ["optimal"]},
    {"id": "optimalLine", "kind": "label", "targetIds": ["optimal"], "text": "x + y = 2"},
    {"id": "maximum", "kind": "callout", "targetIds": ["optimal"], "text": "Z_max = -2", "quantityId": "zMax"}
  ],
  "requiredEntityIds": ["ax", "region", "c02", "c20", "c60", "c06", "optimal"],
  "revealGroups": [
    {"id": "setup", "entityIds": ["ax", "region", "c02", "c20", "c60", "c06"], "dependsOn": []},
    {"id": "result", "entityIds": ["optimal"], "dependsOn": ["setup"]}
  ],
  "teachingTimeline": [
    {"revealGroupId": "setup", "annotationIds": ["objective"]},
    {"revealGroupId": "result", "annotationIds": ["optimalSet", "optimalLine", "maximum"]}
  ]
}

